import { Meta, StoryObj } from "@storybook/react";
import { AdListItem, Props as AdListItemProps } from "./ad-list-item";
import BaseListGroupRenderer from "@/core/components/blocks/list-block/base-list-group-renderer/base-list-group-renderer";
import {
  ShowcaseLayout,
  Variant,
  argTypesComponentTheme,
  showcaseParameters,
  withBlockWrapper,
} from "@/storybook/preview";

type StoryArgs = Omit<AdListItemProps, "callToActionButton"> & {
  buttonLabel?: string;
  buttonUrl?: string;
  buttonOpensInNewTab?: boolean;
  groupHeadline: string;
};

/** Maps the flattened story controls back to the nested `callToActionButton` prop. */
const toAdListItemProps = ({
  buttonLabel,
  buttonUrl,
  buttonOpensInNewTab,
  groupHeadline: _groupHeadline,
  ...args
}: StoryArgs): AdListItemProps => ({
  ...args,
  callToActionButton: { title: buttonLabel, externalUrl: buttonUrl, openInNewTab: buttonOpensInNewTab },
});

/** Renders the items the same way core does (see restaurant-list-renderer): one group inside a
 * BaseListGroupRenderer, so the item gets the block padding, the responsive grid and the cell it
 * stretches into. Rendering the item bare gives a different result, most visibly on mobile.
 * The group headline comes from the story args; `items` defaults to the single item the args describe. */
const InListGroup = ({
  args,
  items = [toAdListItemProps(args)],
}: {
  args: StoryArgs;
  items?: Array<AdListItemProps>;
}) => (
  <BaseListGroupRenderer
    data={[
      {
        id: "story-group",
        headline: args.groupHeadline,
        isExpanded: true,
        listObjects: items.map((item, index) => ({ ...item, id: `item-${index}` })),
      },
    ]}
    isExpandableList={false}
    renderItem={({ id, ...item }) => <AdListItem key={id} {...item} />}
  />
);

const meta: Meta<StoryArgs> = {
  title: "Primitives/Ad List Item",
  component: AdListItem,
  decorators: [withBlockWrapper],
  parameters: {
    docs: {
      description: {
        component:
          "Card that advertises a page or offer inside a list of items, for example among the restaurants or " +
          "attractions. It stretches to the height of its grid cell, so a row of items lines up even when they " +
          "carry different amounts of text. The call-to-action button is optional and needs both a label and a URL. " +
          "The stories render it inside a list group, the same way the restaurant list renderer does in core.",
      },
    },
  },
  argTypes: {
    ...argTypesComponentTheme,
    className: { table: { disable: true } },
    // Story-only controls. Descriptions have to live here: docgen only reads the component's
    // own props type, so jsdoc on StoryArgs would never reach the docs page.
    buttonLabel: { description: "Story-only control: maps to `callToActionButton.title`" },
    buttonUrl: { description: "Story-only control: maps to `callToActionButton.externalUrl`" },
    buttonOpensInNewTab: { description: "Story-only control: maps to `callToActionButton.openInNewTab`" },
    groupHeadline: { description: "Story-only control: headline of the list group the item is rendered in" },
  },
  args: {
    title: "Hållbara menyn",
    preamble: "Här hittar du alla våra vegetariska och veganska alternativ.",
    shortDescriptionInList: "",
    componentTheme: "",
    buttonLabel: "Läs mer",
    buttonUrl: "https://www.gronalund.com",
    buttonOpensInNewTab: false,
    groupHeadline: "Restauranger",
  },
  render: (args) => <InListGroup args={args} />,
};

export default meta;

type Story = StoryObj<StoryArgs>;

export const Default: Story = {};

export const VariantContent: Story = {
  parameters: showcaseParameters,
  render: (args) => {
    const base = toAdListItemProps(args);
    return (
      <ShowcaseLayout title="Content (title, preamble, description, button)" variantType="other">
        <Variant label="title only">
          <InListGroup args={args} items={[{ title: base.title }]} />
        </Variant>
        <Variant label="title + preamble">
          <InListGroup args={args} items={[{ title: base.title, preamble: base.preamble }]} />
        </Variant>
        <Variant label="title + preamble + button">
          <InListGroup args={args} />
        </Variant>
        <Variant label="with short description">
          <InListGroup
            args={args}
            items={[{ ...base, shortDescriptionInList: "...vårt veg är faktiskt grymt gott!" }]}
          />
        </Variant>
        <Variant label="button without url (button is dropped)">
          <InListGroup args={args} items={[{ ...base, callToActionButton: { title: "Läs mer" } }]} />
        </Variant>
      </ShowcaseLayout>
    );
  },
};

export const VariantLayout: Story = {
  parameters: showcaseParameters,
  args: {
    shortDescriptionInList: "...vårt veg är faktiskt grymt gott!",
  },
  render: (args) => {
    const base = toAdListItemProps(args);
    return (
      <ShowcaseLayout title="Layout (position in the list group)" variantType="other">
        <Variant label="alone in the group">
          <InListGroup args={args} />
        </Variant>
        <Variant label="among other items (stretches to the tallest item in the row)">
          <InListGroup
            args={args}
            items={[
              base,
              { ...base, shortDescriptionInList: undefined },
              { ...base, preamble: undefined, shortDescriptionInList: undefined },
              base,
            ]}
          />
        </Variant>
      </ShowcaseLayout>
    );
  },
};
